 }}>موقوف</option></select></label></div></div><fieldset class="permission-grid"><legend>الصلاحيات المسموحة</legend>@foreach($permissionLabels as $value=>$label)<label class="check"><input type="checkbox" name="permissions[]" value="{{ $value }}" {{ in_array($value,$selectedPermissions ?? [],true) ? 'checked':'' }}>{{ $label }}</label>@endforeach</fieldset><p class="note">مدير الفرع يظل مقيدًا بفرعه. الفروع والمشتريات والمرتبات والحسابات متاحة للأدوار المركزية فقط. التصنيع والاستلام يحتاجان أيضًا صلاحية المخزون. إيقاف الحساب يمنع دخوله واستخدام جلساته الحالية.</p><div class="actions"><button>{{ $account ? 'حفظ الحساب':'إنشاء الحساب' }}</button></div></form>
